import{_ as a,a as t,c as o,j as n}from"./chunks/framework.DVzkjf-b.js";const m=JSON.parse('{"title":"About Keith Williams","description":"Keith Williams on teaching at NJIT, building software, working in Zambia, and the experiences behind his work in AI education.","frontmatter":{"title":"About Keith Williams","description":"Keith Williams on teaching at NJIT, building software, working in Zambia, and the experiences behind his work in AI education."},"headers":[],"relativePath":"about.md","filePath":"about.md"}'),r={name:"about.md"};function i(s,e,h,l,d,c){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="about-keith-williams" tabindex="-1">About Keith Williams <a class="header-anchor" href="#about-keith-williams" aria-label="Permalink to &quot;About Keith Williams&quot;">​</a></h1><p>I&#39;m a Senior University Lecturer at the New Jersey Institute of Technology and director of the B.S. in Enterprise AI. I design courses, build software, and study a question that connects the two. When an AI tool helps someone produce good work, how do we tell what that person can do next?</p><h2 id="where-it-started" tabindex="-1">Where it started <a class="header-anchor" href="#where-it-started" aria-label="Permalink to &quot;Where it started&quot;">​</a></h2><p>My father was a mainframe systems lead operator at Alcoa, so computers were part of my world early on. For Christmas in 1983, I received a Tandy TRS-80 Color Computer 2 and started teaching myself to program. There was something wonderful about making a machine do something that had only been an idea a few minutes earlier.</p><p>Before and alongside my university work, I taught children about computers through AmeriCorps at an urban after-school youth center in Pittsburgh. I&#39;ve also worked with high schools. I still care about that first encounter with a tool, especially for the person who isn&#39;t sure they belong in the room.</p><h2 id="building-things-teaching-people" tabindex="-1">Building things, teaching people <a class="header-anchor" href="#building-things-teaching-people" aria-label="Permalink to &quot;Building things, teaching people&quot;">​</a></h2><p>I began teaching at NJIT as an adjunct in 2002. Over more than two decades, I&#39;ve developed courses and helped shape the Web and Information Systems program. I&#39;ve also built software outside the classroom, including Showedme.net, a web application framework and learning management system, and Wrkbench, an iOS collaboration app.</p><p>That experience shapes how I teach. I like projects where someone else can try what the student built and ask a question the student didn&#39;t anticipate. In my AI-assisted Studios, I write instructions for the coach and give the student decisions to own. <a href="/teaching">See the classroom Studios</a></p><h2 id="learning-beyond-my-own-classroom" tabindex="-1">Learning beyond my own classroom <a class="header-anchor" href="#learning-beyond-my-own-classroom" aria-label="Permalink to &quot;Learning beyond my own classroom&quot;">​</a></h2><p>In Zambia, I taught software engineering and worked with government teams on e-government services, user-experience design, and prototyping. The work kept bringing us back to the person trying to use a public service. What did they come to do? Could they do it with the system in front of them? <a href="https://news.njit.edu/inspiring-students-njit-africa" target="_blank" rel="noreferrer">NJIT on teaching in Zambia</a> · <a href="https://news.njit.edu/njit-lecturer-helps-digitize-government-services-zambia" target="_blank" rel="noreferrer">NJIT on digitizing government services</a></p><h2 id="what-i-m-working-on-now" tabindex="-1">What I&#39;m working on now <a class="header-anchor" href="#what-i-m-working-on-now" aria-label="Permalink to &quot;What I&#39;m working on now&quot;">​</a></h2><p>I started using ChatGPT shortly after it launched. Today I build teaching tools and explore how to connect AI-generated answers to evidence people can inspect. You can try a retrieval exercise in the <a href="/knowledge-lab/">Knowledge Lab</a>, look through my <a href="/#projects">public projects</a>, or read my <a href="/research">research questions and technical case studies</a>.</p><p>I also use AI to organize ongoing work. <a href="/life-tracker">Life Tracker</a> shows the everyday version of that problem. How do I keep track of an action I asked an assistant to take and verify what actually happened?</p><p>One idea I&#39;d still like to explore is EverydayAI Newark. I imagined paid workshops helping support free community learning and opportunities for students to demonstrate their work. It remains a proposal, not an operating program.</p><h2 id="let-s-compare-notes" tabindex="-1">Let&#39;s compare notes <a class="header-anchor" href="#let-s-compare-notes" aria-label="Permalink to &quot;Let&#39;s compare notes&quot;">​</a></h2><p>If you&#39;re teaching with AI, I&#39;d like to hear about an assignment that made you rethink your approach. I also welcome conversations about software that helps people inspect the evidence behind an answer. <a href="https://www.linkedin.com/in/keithwilliams5/" target="_blank" rel="noreferrer">Connect on LinkedIn</a> · <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">Find me at NJIT</a> · <a href="/#conversation">Start a public conversation</a></p><p><em>Parts of this account first appeared on my <a href="https://eaikw.com/about/" target="_blank" rel="noreferrer">earlier About page</a>.</em></p>',17)])])}const u=a(r,[["render",i]]);export{m as __pageData,u as default};
